//! Block Puzzle engine: a pure, deterministic function of `Seed + moves`.
//!
//! Only `core` is used (no alloc, no floats, no std), so the same code runs in
//! the on-chain program and in host tests. The TypeScript port in
//! `app/src/games/block-puzzle/engine.ts` must match this file bit for bit;
//! `tests/vectors.json` (generated by `tests/engine.rs`) pins that parity.
//!
//! # Rules
//! * 8x8 grid. Occupancy is a `u64` bitboard (bit `y * 8 + x`), gem cells are a
//!   second `u64` (always a subset of occupancy).
//! * The Seed yields an endless piece sequence. Pieces are dealt in hands of 3:
//!   indices `3k..3k+3` form hand `k`. A move `(piece, x, y)` places one unused
//!   piece of the current hand with its bounding-box top-left at `(x, y)`.
//!   When all 3 are placed the next hand is dealt.
//! * A piece is placed only fully inside the grid, on empty cells.
//! * After placing, every full row and full column clears at once.
//! * Score per move = cells placed + `10 * lines^2 * (1 + gems)` where `lines`
//!   is the number of rows + columns cleared and `gems` the number of gem
//!   cells that were inside the cleared lines (each gem adds +1 to the
//!   multiplier: the Tesoro twist).
//! * About 1 piece in 5 carries one gem on one of its cells.
//! * The game ends when no unused piece of the current hand fits anywhere, or
//!   after `MAX_MOVES`. The 90 s clock is NOT part of the engine: the caller
//!   (Match window on-chain, timer in the UI) stops feeding moves.
//!
//! # PRNG
//! xorshift64* (Vigna): `x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
//! out = x * 0x2545F4914F6CDD1D (mod 2^64)`. Piece `i` is random-access: its
//! state starts at `seed ^ ((i + 1) * 0x9E3779B97F4A7C15)` (0 maps to the
//! golden constant), is warmed up with 4 rounds, then two draws are taken (one
//! round + multiply each): `kind = (draw1 >> 32) % 14`; a gem exists if
//! `(draw2 >> 32) % 5 == 0`, on cell `(draw2 >> 8) % cells` counted in
//! row-major order. Wrapping multiplication is intentional in the PRNG only;
//! all game arithmetic is checked.
//!
//! # Compute
//! Per move: one piece derivation (~6 xorshift rounds), a bitboard overlap
//! test, line detection (16 mask tests), and the game-over scan (<= 3 pieces x
//! <= 64 anchors, each a shift + AND). Estimated ~3k-6k CU per move on SBF,
//! worst case under 10k; a 60-move replay is well under 400k CU. Estimated
//! from operation counts, not yet measured on a BPF harness.

pub const SIZE: u8 = 8;
pub const HAND: u32 = 3;
pub const KINDS: u64 = 14;
pub const MAX_MOVES: u16 = 120;
pub const GEM_ONE_IN: u64 = 5;
pub const LINE_POINTS: u32 = 10;

const ROW0: u64 = 0xFF;
const COL0: u64 = 0x0101_0101_0101_0101;
const GOLDEN: u64 = 0x9E37_79B9_7F4A_7C15;
const XORSHIFT_MUL: u64 = 0x2545_F491_4F6C_DD1D;

/// (width, height, 4x4 mask with bit `y * 4 + x`) per piece kind.
pub const SHAPES: [(u8, u8, u16); KINDS as usize] = [
    (1, 1, 0b1),       // 0 dot
    (2, 1, 0b11),      // 1 domino H
    (1, 2, 0b1_0001),  // 2 domino V
    (3, 1, 0b111),     // 3 line3 H
    (1, 3, 0x111),     // 4 line3 V
    (4, 1, 0b1111),    // 5 line4 H
    (1, 4, 0x1111),    // 6 line4 V
    (2, 2, 0b11_0011), // 7 square
    (2, 2, 0b1_0011),  // 8 L3 ##/#.
    (2, 2, 0b10_0011), // 9 L3 ##/.#
    (2, 2, 0b11_0001), // 10 L3 #./##
    (2, 2, 0b11_0010), // 11 L3 .#/##
    (3, 2, 0b10_0111), // 12 T
    (3, 2, 0b11_0110), // 13 S
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Piece {
    pub kind: u8,
    /// Index (row-major among the piece's cells) of the gem cell, if any.
    pub gem: Option<u8>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Move {
    pub piece: u16,
    pub x: u8,
    pub y: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Error {
    GameOver,
    /// `piece` is not in the current hand.
    BadPiece,
    PieceUsed,
    OutOfBounds,
    Occupied,
    Overflow,
}

impl Error {
    pub fn name(self) -> &'static str {
        match self {
            Error::GameOver => "GameOver",
            Error::BadPiece => "BadPiece",
            Error::PieceUsed => "PieceUsed",
            Error::OutOfBounds => "OutOfBounds",
            Error::Occupied => "Occupied",
            Error::Overflow => "Overflow",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct MoveResult {
    pub gained: u32,
    pub lines: u8,
    pub gems: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct State {
    pub seed: u64,
    pub occ: u64,
    pub gems: u64,
    pub score: u32,
    pub moves: u16,
    /// Bit `n` set: piece `3 * (moves / 3) + n` is already placed.
    pub used: u8,
    pub over: bool,
}

fn next(x: u64) -> u64 {
    let mut x = x;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    x
}

/// Piece `index` of the sequence for `seed`.
#[allow(unknown_lints, clippy::manual_is_multiple_of)]
pub fn piece_at(seed: u64, index: u32) -> Piece {
    let mut s = seed ^ (u64::from(index).wrapping_add(1)).wrapping_mul(GOLDEN);
    if s == 0 {
        s = GOLDEN;
    }
    s = next(next(next(next(s))));
    s = next(s);
    let d1 = s.wrapping_mul(XORSHIFT_MUL);
    s = next(s);
    let d2 = s.wrapping_mul(XORSHIFT_MUL);
    let kind = ((d1 >> 32) % KINDS) as u8;
    let cells = u64::from(SHAPES[kind as usize].2.count_ones());
    let gem = if (d2 >> 32) % GEM_ONE_IN == 0 {
        Some(((d2 >> 8) % cells) as u8)
    } else {
        None
    };
    Piece { kind, gem }
}

/// Footprint at anchor (0, 0) on the 8x8 bitboard, and its gem bit (0 if none).
pub fn footprint(piece: Piece) -> (u64, u64) {
    let mask = SHAPES[piece.kind as usize].2;
    let mut bits = 0u64;
    let mut gem = 0u64;
    let mut n = 0u8;
    let mut i = 0u32;
    while i < 16 {
        if (mask >> i) & 1 == 1 {
            let bit = 1u64 << ((i / 4) * 8 + i % 4);
            bits |= bit;
            if piece.gem == Some(n) {
                gem = bit;
            }
            n += 1;
        }
        i += 1;
    }
    (bits, gem)
}

pub fn dims(piece: Piece) -> (u8, u8) {
    let s = SHAPES[piece.kind as usize];
    (s.0, s.1)
}

impl State {
    pub fn new(seed: u64) -> Self {
        State {
            seed,
            occ: 0,
            gems: 0,
            score: 0,
            moves: 0,
            used: 0,
            over: false,
        }
    }

    pub fn hand_base(&self) -> u32 {
        (u32::from(self.moves) / HAND) * HAND
    }

    /// Whether `piece` fits at some anchor on the current board.
    pub fn fits_anywhere(&self, piece: Piece) -> bool {
        let (bits, _) = footprint(piece);
        let (w, h) = dims(piece);
        let mut y = 0;
        while y <= SIZE - h {
            let mut x = 0;
            while x <= SIZE - w {
                if self.occ & (bits << (y * SIZE + x)) == 0 {
                    return true;
                }
                x += 1;
            }
            y += 1;
        }
        false
    }

    fn any_fits(&self) -> bool {
        let base = self.hand_base();
        (0..HAND)
            .any(|n| self.used >> n & 1 == 0 && self.fits_anywhere(piece_at(self.seed, base + n)))
    }

    pub fn apply(&mut self, mv: Move) -> Result<MoveResult, Error> {
        if self.over {
            return Err(Error::GameOver);
        }
        let idx = u32::from(mv.piece);
        let base = self.hand_base();
        if idx < base || idx >= base + HAND {
            return Err(Error::BadPiece);
        }
        let slot = idx - base;
        if self.used >> slot & 1 == 1 {
            return Err(Error::PieceUsed);
        }
        let piece = piece_at(self.seed, idx);
        let (w, h) = dims(piece);
        if u16::from(mv.x) + u16::from(w) > u16::from(SIZE)
            || u16::from(mv.y) + u16::from(h) > u16::from(SIZE)
        {
            return Err(Error::OutOfBounds);
        }
        let shift = mv.y * SIZE + mv.x;
        let (bits, gem) = footprint(piece);
        let bits = bits << shift;
        if self.occ & bits != 0 {
            return Err(Error::Occupied);
        }

        let mut occ = self.occ | bits;
        let mut gems = self.gems | (gem << shift);
        let mut clear = 0u64;
        let mut lines = 0u8;
        for i in 0..SIZE {
            let row = ROW0 << (i * SIZE);
            if occ & row == row {
                clear |= row;
                lines += 1;
            }
            let col = COL0 << i;
            if occ & col == col {
                clear |= col;
                lines += 1;
            }
        }
        let gem_hits = (gems & clear).count_ones();
        let mut gained = bits.count_ones();
        if lines > 0 {
            let l = u32::from(lines);
            let line_score = LINE_POINTS
                .checked_mul(l)
                .and_then(|v| v.checked_mul(l))
                .and_then(|v| v.checked_mul(1 + gem_hits))
                .ok_or(Error::Overflow)?;
            gained = gained.checked_add(line_score).ok_or(Error::Overflow)?;
        }
        let score = self.score.checked_add(gained).ok_or(Error::Overflow)?;

        occ &= !clear;
        gems &= !clear;
        self.occ = occ;
        self.gems = gems;
        self.score = score;
        self.moves += 1;
        self.used |= 1 << slot;
        if self.used == 7 {
            self.used = 0;
        }
        self.over = self.moves >= MAX_MOVES || !self.any_fits();
        Ok(MoveResult {
            gained,
            lines,
            gems: gem_hits as u8,
        })
    }
}

/// Replays `moves` from a fresh game. Any invalid move rejects the whole run,
/// returning its index.
pub fn replay(seed: u64, moves: &[Move]) -> Result<State, (usize, Error)> {
    let mut st = State::new(seed);
    for (i, m) in moves.iter().enumerate() {
        st.apply(*m).map_err(|e| (i, e))?;
    }
    Ok(st)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dot_seed() -> u64 {
        (0..u64::MAX)
            .find(|s| piece_at(*s, 0).kind == 0 && piece_at(*s, 0).gem.is_none())
            .unwrap()
    }

    #[test]
    fn shapes_are_consistent() {
        for (w, h, mask) in SHAPES {
            let mut mw = 0;
            let mut mh = 0;
            for i in 0..16u16 {
                if mask >> i & 1 == 1 {
                    mw = mw.max((i % 4) as u8 + 1);
                    mh = mh.max((i / 4) as u8 + 1);
                }
            }
            assert_eq!((w, h), (mw, mh));
        }
    }

    #[test]
    fn piece_is_deterministic_and_varied() {
        assert_eq!(piece_at(7, 3), piece_at(7, 3));
        let kinds: std::collections::BTreeSet<u8> =
            (0..200).map(|i| piece_at(42, i).kind).collect();
        assert_eq!(kinds.len(), KINDS as usize);
        let gems = (0..1000).filter(|i| piece_at(9, *i).gem.is_some()).count();
        assert!((120..280).contains(&gems), "gem rate {gems}/1000");
    }

    #[test]
    fn zero_seed_works() {
        let _ = piece_at(0, 0);
        assert!(!State::new(0).over);
    }

    #[test]
    fn rejects_bad_moves() {
        let mut st = State::new(1);
        assert_eq!(
            st.apply(Move {
                piece: 3,
                x: 0,
                y: 0
            }),
            Err(Error::BadPiece)
        );
        let (w, _) = dims(piece_at(1, 0));
        assert_eq!(
            st.apply(Move {
                piece: 0,
                x: SIZE - w + 1,
                y: 0
            }),
            Err(Error::OutOfBounds)
        );
        assert!(st
            .apply(Move {
                piece: 0,
                x: 0,
                y: 0
            })
            .is_ok());
        assert_eq!(
            st.apply(Move {
                piece: 0,
                x: 0,
                y: 4
            }),
            Err(Error::PieceUsed)
        );
        assert_eq!(
            st.apply(Move {
                piece: 1,
                x: 0,
                y: 0
            }),
            Err(Error::Occupied)
        );
    }

    #[test]
    fn row_clear_with_gem_multiplier() {
        let mut st = State::new(dot_seed());
        st.occ = 0x7F << 56;
        st.gems = 1 << 56;
        let r = st
            .apply(Move {
                piece: 0,
                x: 7,
                y: 7,
            })
            .unwrap();
        assert_eq!((r.lines, r.gems), (1, 1));
        assert_eq!(r.gained, 1 + LINE_POINTS * 2);
        assert_eq!((st.occ, st.gems), (0, 0));
    }

    #[test]
    fn row_and_column_together() {
        let mut st = State::new(dot_seed());
        st.occ = (ROW0 | COL0) & !1;
        let r = st
            .apply(Move {
                piece: 0,
                x: 0,
                y: 0,
            })
            .unwrap();
        assert_eq!(r.lines, 2);
        assert_eq!(r.gained, 1 + LINE_POINTS * 4);
        assert_eq!(st.occ, 0);
    }

    #[test]
    fn game_over_when_nothing_fits() {
        let seed = (0..u64::MAX)
            .find(|s| {
                piece_at(*s, 0).kind == 0 && piece_at(*s, 1).kind != 0 && piece_at(*s, 2).kind != 0
            })
            .unwrap();
        let mut st = State::new(seed);
        st.occ = 0xAA55_AA55_AA55_AA55; // checkerboard: only single cells are free
        assert!(!st.over);
        let r = st
            .apply(Move {
                piece: 0,
                x: 0,
                y: 1,
            })
            .unwrap();
        assert_eq!(r.lines, 0);
        assert!(st.over);
        assert_eq!(
            st.apply(Move {
                piece: 1,
                x: 0,
                y: 0
            }),
            Err(Error::GameOver)
        );
    }

    #[test]
    fn hand_rolls_over() {
        let mut st = State::new(3);
        for i in 0..3u16 {
            let mut placed = false;
            'o: for y in 0..SIZE {
                for x in 0..SIZE {
                    let mut t = st;
                    if t.apply(Move { piece: i, x, y }).is_ok() {
                        st = t;
                        placed = true;
                        break 'o;
                    }
                }
            }
            assert!(placed);
        }
        assert_eq!(st.used, 0);
        assert_eq!(st.hand_base(), 3);
    }
}
